#!/usr/bin/env python3
"""Companion-protocol vectors for the mesh tools (protocol §15.8, §16; MeshCore v1.18, commit 81dbae5).

Written from the firmware itself, with Python's struct: nothing is shared with the Rust code.
Sources, at https://github.com/meshcore-dev/MeshCore/blob/81dbae5/ :
  examples/companion_radio/MyMesh.cpp       (the companion: command handlers and pushes)
  src/helpers/BaseChatMesh.cpp              (what the companion sends on the air)
  examples/simple_repeater/MyMesh.{cpp,h}   (a repeater's answers)
  examples/simple_room_server/MyMesh.cpp    (a room server's answers)
  docs/qr_codes.md                          (the stock app's QR codes)
  src/Mesh.cpp, src/Packet.cpp, src/helpers/AdvertDataHelpers.cpp   (a node's signed advert)
The line of each handler is given. Adverts are signed with test keys by the RFC 8032 reference
Ed25519 below (Python has none). Regenerate with:
    python3 -I testdata/meshcore/mesh.py > testdata/meshcore/mesh.toml
"""
import hashlib
import struct
import urllib.parse

# --- Ed25519, RFC 8032 §6 (the reference code, unchanged but for names) ---------------------
P = 2**255 - 19
Q = 2**252 + 27742317777372353535851937790883648493
D = -121665 * pow(121666, P - 2, P) % P


def _add(a, b):
    x = (a[1] - a[0]) * (b[1] - b[0]) % P
    y = (a[1] + a[0]) * (b[1] + b[0]) % P
    c, d = 2 * a[3] * b[3] * D % P, 2 * a[2] * b[2] % P
    e, f, g, h = y - x, d - c, d + c, y + x
    return (e * f, g * h, f * g, e * h)


def _mul(s, pt):
    q = (0, 1, 1, 0)
    while s > 0:
        if s & 1:
            q = _add(q, pt)
        pt = _add(pt, pt)
        s >>= 1
    return q


def _recover_x(y, sign):
    if y >= P:
        return None
    x2 = (y * y - 1) * pow(D * y * y + 1, P - 2, P)
    if x2 == 0:
        return None if sign else 0
    x = pow(x2, (P + 3) // 8, P)
    if (x * x - x2) % P != 0:
        x = x * pow(2, (P - 1) // 4, P) % P
    if (x * x - x2) % P != 0:
        return None
    if (x & 1) != sign:
        x = P - x
    return x


_GY = 4 * pow(5, P - 2, P) % P
_GX = _recover_x(_GY, 0)
G = (_GX, _GY, 1, _GX * _GY % P)


def _compress(pt):
    zinv = pow(pt[2], P - 2, P)
    x, y = pt[0] * zinv % P, pt[1] * zinv % P
    return int.to_bytes(y | ((x & 1) << 255), 32, "little")


def _decompress(s):
    y = int.from_bytes(s, "little")
    sign = y >> 255
    y &= (1 << 255) - 1
    x = _recover_x(y, sign)
    return None if x is None else (x, y, 1, x * y % P)


def _hq(*parts):
    return int.from_bytes(hashlib.sha512(b"".join(parts)).digest(), "little") % Q


def _expand(seed):
    h = hashlib.sha512(seed).digest()
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    return a, h[32:]


def ed25519_public(seed):
    return _compress(_mul(_expand(seed)[0], G))


def ed25519_sign(seed, msg):
    a, prefix = _expand(seed)
    pub = _compress(_mul(a, G))
    r = _hq(prefix, msg)
    rs = _compress(_mul(r, G))
    return rs + int.to_bytes((r + _hq(rs, pub, msg) * a) % Q, 32, "little")


def ed25519_verify(pub, msg, sig):
    a, r = _decompress(pub), _decompress(sig[:32])
    s = int.from_bytes(sig[32:], "little")
    if a is None or r is None or s >= Q:
        return False
    h = _hq(sig[:32], pub, msg)
    lhs, rhs = _mul(s, G), _add(r, _mul(h, a))
    return (lhs[0] * rhs[2] - rhs[0] * lhs[2]) % P == 0 and (lhs[1] * rhs[2] - rhs[1] * lhs[2]) % P == 0


def out(section, name, frame, source, **fields):
    print(f"[[{section}]]")
    print(f'name = "{name}"')
    if isinstance(frame, str):
        print(f'text = "{frame}"')
    else:
        print(f'hex = "{frame.hex()}"')
    for k, v in fields.items():
        if isinstance(v, bool):
            print(f"{k} = {str(v).lower()}")
        elif isinstance(v, (bytes, bytearray)):
            print(f'{k} = "{bytes(v).hex()}"')
        elif isinstance(v, str):
            print(f'{k} = "{v}"')
        elif isinstance(v, list):
            print(f"{k} = [{', '.join(str(x) for x in v)}]")
        else:
            print(f"{k} = {v}")
    print(f'source = "{source}"')
    print()


def main():
    print("# Mesh tools, companion protocol v1.18 (81dbae5). Generated by mesh.py: do not edit.\n")

    # --- Traces (§16.3) ---------------------------------------------------------------------
    # CMD_SEND_TRACE_PATH (36), MyMesh.cpp#L1813: tag u32, auth u32, flags (path_sz in bits
    # 0-1, hashes of 1 << path_sz bytes), then the path to trace.
    path = bytes([0x5A, 0x77, 0x5A])
    out("command", "send-trace-path", struct.pack("<BIIB", 36, 0x12345678, 0, 0) + path,
        "MyMesh.cpp#L1813", tag=0x12345678, auth=0, flags=0, path=path)
    path2 = bytes([0x5A, 0x01, 0x77, 0x02, 0x5A, 0x01])
    out("command", "send-trace-path-2-byte", struct.pack("<BIIB", 36, 0xCAFE0001, 7, 1) + path2,
        "MyMesh.cpp#L1813", tag=0xCAFE0001, auth=7, flags=1, path=path2)
    # PUSH_CODE_TRACE_DATA (0x89), MyMesh.cpp#L855: reserved, path_len (bytes of hashes),
    # flags, tag, auth, hashes, one SNR x 4 per hop (path_len >> path_sz), our final SNR x 4.
    snrs = [40, -12, 22]
    frame = (struct.pack("<BBBBII", 0x89, 0, len(path), 0, 0x12345678, 0) + path
             + struct.pack("<3b", *snrs) + struct.pack("<b", 30))
    out("response", "trace-data", frame, "MyMesh.cpp#L855", tag=0x12345678, auth=0, flags=0,
        hashes=path, snrs=snrs, final_snr4=30)
    snrs2 = [-4, 8, 16]
    frame = (struct.pack("<BBBBII", 0x89, 0, len(path2), 1, 0xCAFE0001, 7) + path2
             + struct.pack("<3b", *snrs2) + struct.pack("<b", -20))
    out("response", "trace-data-2-byte", frame, "MyMesh.cpp#L855", tag=0xCAFE0001, auth=7, flags=1,
        hashes=path2, snrs=snrs2, final_snr4=-20)

    # --- Room servers and repeaters (§15.8, §16.5) -------------------------------------------
    room = bytes(range(0x30, 0x50))
    rpt = bytes(range(0x60, 0x80))
    # CMD_SEND_LOGIN (26), MyMesh.cpp#L1577: key, password (BaseChatMesh::sendLogin keeps 15
    # bytes); the companion answers RESP_CODE_SENT with the key's first 4 bytes as its tag.
    out("command", "send-login", bytes([26]) + room + b"hello", "MyMesh.cpp#L1577",
        key=room, password="hello")
    # CMD_SEND_STATUS_REQ (27), MyMesh.cpp#L1630; CMD_LOGOUT (29), MyMesh.cpp#L1748.
    out("command", "send-status-req", bytes([27]) + rpt, "MyMesh.cpp#L1630", key=rpt)
    out("command", "logout", bytes([29]) + rpt, "MyMesh.cpp#L1748", key=rpt)
    # CMD_SEND_BINARY_REQ (50), MyMesh.cpp#L1720, with a repeater's REQ_TYPE_GET_NEIGHBOURS
    # (0x06), simple_repeater/MyMesh.cpp#L276: version 0, count, offset u16, order (2:
    # strongest first), key prefix length, 4 random bytes.
    req = struct.pack("<BBBHBB", 6, 0, 255, 0, 2, 6) + bytes([1, 2, 3, 4])
    out("command", "send-binary-req-neighbours", bytes([50]) + rpt + req, "MyMesh.cpp#L1720",
        key=rpt, count=255, offset=0, order=2, prefix_len=6, random=bytes([1, 2, 3, 4]))
    # CMD_SEND_TXT_MSG (2) with TXT_TYPE_CLI_DATA (1), MyMesh.cpp#L1132: a console command.
    out("command", "send-txt-msg-cli", struct.pack("<BBBI", 2, 1, 0, 1_793_000_000) + rpt[:6] + b"ver",
        "MyMesh.cpp#L1132", kind=1, attempt=0, ts=1_793_000_000, prefix=rpt[:6], text="ver")

    # CMD_SEND_TELEMETRY_REQ (39), MyMesh.cpp#L1680: three reserved bytes, then the key (the
    # handler reads it at offset 4, `len >= 4 + PUB_KEY_SIZE`; `len == 4` asks our own radio).
    out("command", "send-telemetry-req", bytes([39, 0, 0, 0]) + rpt, "MyMesh.cpp#L1680", key=rpt)

    # CMD_GET_STATS (56), MyMesh.cpp#L1914: the stats type (0 core, 1 radio, 2 packets, L70-L73).
    for kind in (0, 1, 2):
        out("command", f"get-stats-{kind}", bytes([56, kind]), "MyMesh.cpp#L1914", kind=kind)

    # RESP_CODE_STATS (24), MyMesh.cpp#L1916-L1962: the type, then its figures, little-endian.
    out("response", "stats-core", struct.pack("<BBHIHB", 24, 0, 3_990, 86_520, 0, 2),
        "MyMesh.cpp#L1916", battery_mv=3_990, uptime_s=86_520, err_flags=0, queue_len=2)
    out("response", "stats-radio", struct.pack("<BBhbbII", 24, 1, -116, -98, 27, 412, 1_830),
        "MyMesh.cpp#L1928", noise=-116, rssi=-98, snr4=27, tx_air_s=412, rx_air_s=1_830)
    out("response", "stats-packets", struct.pack("<BB7I", 24, 2, 5_120, 830, 610, 220, 3_900, 1_220, 14),
        "MyMesh.cpp#L1943", recv=5_120, sent=830, sent_flood=610, sent_direct=220,
        recv_flood=3_900, recv_direct=1_220, recv_errors=14)
    # RESP_CODE_DEVICE_INFO (13), MyMesh.cpp#L1056-L1074, as a ThinkNode M5 companion at v1.18
    # sends it: FIRMWARE_VER_CODE 14 (MyMesh.h#L7), MAX_CONTACTS 350 / 2 and MAX_GROUP_CHANNELS 40
    # (variants/thinknode_m5/platformio.ini#L149-L150), the BLE PIN, the build date in 12 bytes
    # (MyMesh.h#L10), the manufacturer in 40 (ThinknodeM5Board.cpp#L38), the version in 20
    # (MyMesh.h#L14), repeat off, path hash mode 0.
    def padded(text, n):
        return text.encode() + bytes(n - len(text))
    info = (bytes([13, 14, 175, 40]) + struct.pack("<I", 0) + padded("15 Oct 2026", 12)
            + padded("Elecrow ThinkNode M5", 40) + padded("v1.18.0", 20) + bytes([0, 0]))
    out("response", "device-info-thinknode-m5", info, "MyMesh.cpp#L1056", fw_ver=14,
        max_channels=40, build_date="15 Oct 2026", manufacturer="Elecrow ThinkNode M5",
        version="v1.18.0", repeat=False, path_hash_mode=0)

    # PUSH_CODE_LOGIN_SUCCESS (0x85), MyMesh.cpp#L704: is_admin, key prefix, the server's
    # clock, our permissions (simple_repeater/MyMesh.cpp#L137: role 3 admin), firmware level.
    out("response", "login-success", bytes([0x85, 1]) + rpt[:6] + struct.pack("<IBB", 1_793_000_123, 3, 2),
        "MyMesh.cpp#L704", admin=1, prefix=rpt[:6], server_time=1_793_000_123, permissions=3,
        fw_level=2)
    # A room server's guest (simple_room_server/MyMesh.cpp#L385: role 2, read and write).
    out("response", "login-success-room", bytes([0x85, 0]) + room[:6] + struct.pack("<IBB", 1_793_000_200, 2, 1),
        "MyMesh.cpp#L704", admin=0, prefix=room[:6], server_time=1_793_000_200, permissions=2,
        fw_level=1)
    # The legacy answer ("OK"), MyMesh.cpp#L699: is_admin 0, key prefix, nothing more.
    out("response", "login-success-legacy", bytes([0x85, 0]) + rpt[:6], "MyMesh.cpp#L699",
        admin=0, prefix=rpt[:6])
    # PUSH_CODE_LOGIN_FAIL (0x86), MyMesh.cpp#L717.
    out("response", "login-fail", bytes([0x86, 0]) + rpt[:6], "MyMesh.cpp#L717", prefix=rpt[:6])
    # PUSH_CODE_STATUS_RESPONSE (0x87), MyMesh.cpp#L724: reserved, key prefix, the stats
    # after the 4-byte tag. RepeaterStats, simple_repeater/MyMesh.h#L44 (56 bytes).
    stats = struct.pack("<HHhhIIIIIIIIHhHHII", 4012, 1, -112, -71, 5000, 1200, 340, 86_400,
                        700, 500, 3000, 2000, 0, 31, 12, 40, 900, 7)
    assert len(stats) == 56
    out("response", "status-response-repeater", bytes([0x87, 0]) + rpt[:6] + stats,
        "MyMesh.cpp#L724", prefix=rpt[:6], battery_mv=4012, tx_queue=1, noise_floor=-112,
        last_rssi=-71, packets_recv=5000, packets_sent=1200, air_time_s=340, uptime_s=86_400,
        sent_flood=700, sent_direct=500, recv_flood=3000, recv_direct=2000, err_events=0,
        last_snr4=31, direct_dups=12, flood_dups=40, rx_air_time_s=900, recv_errors=7)
    # ServerStats, simple_room_server/MyMesh.cpp#L24 (52 bytes).
    stats = struct.pack("<HHhhIIIIIIIIHhHHHH", 3900, 0, -115, -80, 800, 300, 60, 3_600,
                        100, 200, 400, 400, 0, -8, 1, 2, 25, 60)
    assert len(stats) == 52
    out("response", "status-response-room", bytes([0x87, 0]) + room[:6] + stats,
        "MyMesh.cpp#L724", prefix=room[:6], battery_mv=3900, uptime_s=3_600, last_snr4=-8,
        posted=25, post_pushes=60)
    # PUSH_CODE_TELEMETRY_RESPONSE (0x8B), MyMesh.cpp#L739-L748: reserved, key prefix, the
    # CayenneLPP readings after the node's 4-byte tag (simple_repeater/MyMesh.cpp#L240-L260):
    # channel 1 voltage 3.92 V (type 116, 0.01 V, big-endian) and temperature 4.0 C (type 103,
    # 0.1 C).
    lpp = bytes([1, 116]) + (392).to_bytes(2, "big") + bytes([1, 103]) + (40).to_bytes(2, "big")
    out("response", "telemetry-response", bytes([0x8B, 0]) + rpt[:6] + lpp, "MyMesh.cpp#L739",
        prefix=rpt[:6], data=lpp)

    # PUSH_CODE_BINARY_RESPONSE (0x8C), MyMesh.cpp#L750: reserved, tag, the answer after its
    # tag; GET_NEIGHBOURS' answer, simple_repeater/MyMesh.cpp#L341-L360: total, count, and per
    # neighbour its key prefix, seconds since heard (u32), SNR x 4 (i8).
    entries = [(bytes(range(0xA0, 0xA6)), 30, 38), (bytes(range(0xB0, 0xB6)), 600, -10)]
    body = struct.pack("<HH", 5, len(entries)) + b"".join(p + struct.pack("<Ib", a, s) for p, a, s in entries)
    out("response", "binary-response-neighbours", struct.pack("<BBI", 0x8C, 0, 0x01020304) + body,
        "MyMesh.cpp#L750", tag=0x01020304, total=5, count=2,
        prefixes=b"".join(p for p, _, _ in entries), heard_ago_s=[30, 600], snrs=[38, -10])
    # A room server's post, queued as RESP_CODE_CONTACT_MSG_RECV_V3 (0x10) with
    # TXT_TYPE_SIGNED_PLAIN (2), MyMesh.cpp#L440 and #L550: the author's 4-byte key prefix
    # before the text (simple_room_server/MyMesh.cpp#L69).
    author = bytes([0xA0, 0xA1, 0xA2, 0xA3])
    out("response", "contact-msg-room-post",
        struct.pack("<BbBB", 0x10, 24, 0, 0) + room[:6] + struct.pack("<BBI", 1, 2, 1_793_000_300) + author + b"Snow above 2000 m",
        "MyMesh.cpp#L550", prefix=room[:6], path_len=1, kind=2, ts=1_793_000_300, author=author,
        text="Snow above 2000 m")
    # A console reply, TXT_TYPE_CLI_DATA (1), MyMesh.cpp#L533.
    out("response", "contact-msg-cli-reply",
        struct.pack("<BbBB", 0x10, 30, 0, 0) + rpt[:6] + struct.pack("<BBI", 0xFF, 1, 1_793_000_301) + b"v1.18.0",
        "MyMesh.cpp#L533", prefix=rpt[:6], path_len=255, kind=1, ts=1_793_000_301, text="v1.18.0")

    # --- Private channels by QR code (§15.3) --------------------------------------------------
    # docs/qr_codes.md: meshcore://channel/add?name=<URL-encoded>&secret=<32 hex digits>, and
    # an optional region_scope. Written with urllib's percent-encoding, read back with its
    # query parser ('+' is a space there too).
    def qr(name, url, channel_name, secret):
        q = urllib.parse.parse_qs(urllib.parse.urlsplit(url).query)
        assert q["name"] == [channel_name] and q["secret"] == [secret.hex()], url
        out("qr", name, url, "docs/qr_codes.md", channel_name=channel_name, secret=secret)

    for name, channel_name, secret in [
        ("channel-public", "Public", bytes.fromhex("8b3387e9c5cdea6ac9e5edbaa115cd72")),
        ("channel-encoded", "Refuge été & co", bytes(range(0x00, 0x100, 0x11))),
    ]:
        url = f"meshcore://channel/add?name={urllib.parse.quote(channel_name, safe='')}&secret={secret.hex()}"
        qr(name, url, channel_name, secret)
    # Another writer's order, '+' for spaces and a region scope.
    secret = bytes(range(15, -1, -1))
    url = f"meshcore://channel/add?secret={secret.hex()}&{urllib.parse.urlencode({'name': 'Hut team', 'region_scope': 'alps'})}"
    qr("channel-plus-and-scope", url, "Hut team", secret)

    # --- A node's contact code (§15.3) --------------------------------------------------------
    # docs/qr_codes.md: meshcore://contact/add?name=<URL-encoded>&public_key=<64 hex digits>
    # &type=<1 companion, 2 repeater, 3 room server, 4 sensor>. Read with urllib's parser;
    # refused when the key is not 64 hex digits, the type not 1 to 4, or the name empty or
    # longer than 31 bytes (a MeshCore name).
    def read_contact(url):
        parts = urllib.parse.urlsplit(url)
        if f"{parts.scheme}://{parts.netloc}{parts.path}" != "meshcore://contact/add":
            return None
        q = urllib.parse.parse_qs(parts.query, keep_blank_values=True)
        name, key = q.get("name", [""])[0].strip(), q.get("public_key", [""])[0]
        kind = {"1": 1, "2": 2, "3": 3, "4": 4}.get(q.get("type", [""])[0])
        if len(key) != 64 or any(c not in "0123456789abcdefABCDEF" for c in key):
            return None
        if kind is None or not name or len(name.encode()) > 31:
            return None
        return name, bytes.fromhex(key), kind

    def contact(name, url, contact_name, key, kind):
        assert read_contact(url) == (contact_name, key, kind), url
        out("qr", name, url, "docs/qr_codes.md", contact_name=contact_name, public_key=key,
            node_type=kind)

    # The documentation's own example, as it is written there ('+' for the space).
    contact("contact-doc-example",
            "meshcore://contact/add?name=Example+Contact&public_key="
            "9cd8fcf22a47333b591d96a2b848b73f457b1bb1a3ea2453a885f9e5787765b1&type=1",
            "Example Contact",
            bytes.fromhex("9cd8fcf22a47333b591d96a2b848b73f457b1bb1a3ea2453a885f9e5787765b1"), 1)
    # As lichen writes them: name, public_key, type, the name percent-encoded.
    for name, contact_name, key, kind in [
        ("contact-companion", "ThinkNode M5", bytes(range(0xA0, 0xC0)), 1),
        ("contact-room-encoded", "Refuge board · été", bytes(range(32)), 3),
    ]:
        url = (f"meshcore://contact/add?name={urllib.parse.quote(contact_name, safe='')}"
               f"&public_key={key.hex()}&type={kind}")
        contact(name, url, contact_name, key, kind)
    # Another writer's order, an upper-case key, '+' for the space, a parameter we ignore.
    key = bytes(range(0x40, 0x60))
    contact("contact-repeater-order",
            f"meshcore://contact/add?type=2&public_key={key.hex().upper()}&name=hub+west&ttl=3",
            "hub west", key, 2)
    # Refused.
    good = "9cd8fcf22a47333b591d96a2b848b73f457b1bb1a3ea2453a885f9e5787765b1"
    for name, url in [
        ("contact-short-key", f"meshcore://contact/add?name=x&public_key={good[:62]}&type=1"),
        ("contact-key-not-hex", f"meshcore://contact/add?name=x&public_key=zz{good[2:]}&type=1"),
        ("contact-type-0", f"meshcore://contact/add?name=x&public_key={good}&type=0"),
        ("contact-type-5", f"meshcore://contact/add?name=x&public_key={good}&type=5"),
        ("contact-no-type", f"meshcore://contact/add?name=x&public_key={good}"),
        ("contact-empty-name", f"meshcore://contact/add?name=&public_key={good}&type=1"),
        ("contact-long-name", f"meshcore://contact/add?name={'a' * 32}&public_key={good}&type=1"),
        ("contact-channel-path", f"meshcore://channel/add?name=x&public_key={good}&type=1"),
    ]:
        assert read_contact(url) is None, url
        out("qr", name, url, "docs/qr_codes.md", refused=True)

    # --- A node's shared contact link (§15.3, §16.6) -------------------------------------------
    # meshcore:// + the hex of the packet EXPORT_CONTACT returns (MyMesh.cpp#L1379): header 0x11
    # (ADVERT, flood) ‖ path_len ‖ path ‖ key (32) ‖ timestamp u32 ‖ signature (64) ‖ app_data
    # (Packet.cpp#L52, Mesh.cpp#L404). app_data (AdvertDataHelpers.cpp#L4): flags (type in bits
    # 0-3, 0x10 position, 0x20 and 0x40 two u16 fields, 0x80 name) ‖ [lat i32 ‖ lon i32] ‖
    # [feat1 u16] ‖ [feat2 u16] ‖ name, 32 bytes at most (MeshCore.h#L12). The signature covers
    # key ‖ timestamp ‖ app_data (Mesh.cpp#L271). lichen imports the packet as the link holds
    # it, path included (IMPORT_CONTACT, MyMesh.cpp#L1409: the radio caches the path as the
    # advert's, L358-L388), and adds the contact with ADD_UPDATE_CONTACT (MyMesh.cpp#L1328,
    # updateContactFromFrame L194), with no path of its own, when the radio did not take it.
    def app_data(kind, name, pos=None, feat1=None, feat2=None):
        flags, rest = kind, b""
        if pos is not None:
            flags |= 0x10
            rest += struct.pack("<ii", *pos)
        if feat1 is not None:
            flags |= 0x20
            rest += struct.pack("<H", feat1)
        if feat2 is not None:
            flags |= 0x40
            rest += struct.pack("<H", feat2)
        if name:
            flags |= 0x80
            rest += name
        return bytes([flags]) + rest

    def advert(seed, ts, data, header=0x11, path=b"", path_len=None, sign_over=None):
        key = ed25519_public(seed)
        signed = key + struct.pack("<I", ts) + (data if sign_over is None else sign_over)
        payload = key + struct.pack("<I", ts) + ed25519_sign(seed, signed) + data
        return bytes([header, len(path) if path_len is None else path_len]) + path + payload

    def read_link(text):
        """(name, key, kind, position, timestamp, path, packet), or "code" / "signature"."""
        if not text.startswith("meshcore://"):
            return "code"
        h = text[len("meshcore://"):]
        if not h or len(h) % 2 or any(c not in "0123456789abcdefABCDEF" for c in h):
            return "code"
        raw = bytes.fromhex(h)
        if len(raw) < 2 or raw[0] != 0x11:
            return "code"
        size, count = (raw[1] >> 6) + 1, raw[1] & 63
        if size == 4 or size * count > 64 or len(raw) < 2 + size * count:
            return "code"
        payload = raw[2 + size * count:]
        if len(payload) < 32 + 4 + 64 + 1 or len(payload) > 32 + 4 + 64 + 32:
            return "code"
        key, ts, sig, data = payload[:32], payload[32:36], payload[36:100], payload[100:]
        flags, i = data[0], 1
        pos = None
        if flags & 0x10:
            if len(data) < i + 8:
                return "code"
            pos = struct.unpack_from("<ii", data, i)
            i += 8
        for bit in (0x20, 0x40):
            if flags & bit:
                if len(data) < i + 2:
                    return "code"
                i += 2
        name = data[i:]
        if flags & 0x0F not in (1, 2, 3, 4) or not flags & 0x80 or not name or b"\0" in name:
            return "code"
        try:
            name = name.decode("utf-8")
        except UnicodeDecodeError:
            return "code"
        if not ed25519_verify(key, key + ts + data, sig):
            return "signature"
        if pos == (0, 0):
            pos = None
        return name, key, flags & 0x0F, pos, struct.unpack("<I", ts)[0], (count, raw[2:2 + size * count]), raw

    def add_frame(key, kind, name, ts, pos):
        lat, lon = pos or (0, 0)
        return (bytes([9]) + key + bytes([kind, 0, 0xFF]) + bytes(64)
                + name.encode().ljust(32, b"\0") + struct.pack("<Iii", ts, lat, lon))

    def link(vname, text, source="MyMesh.cpp#L1409"):
        r = read_link(text)
        assert isinstance(r, tuple), (vname, r)
        name, key, kind, pos, ts, (hops, path), packet = r
        fields = dict(contact_name=name, public_key=key, node_type=kind, timestamp=ts, signed=True,
                      hops=hops, path=path)
        if pos:
            fields.update(lat_e6=pos[0], lon_e6=pos[1])
        fields.update(import_frame=bytes([18]) + packet, add_frame=add_frame(key, kind, name, ts, pos))
        out("link", vname, text, source, **fields)

    def refused(vname, text, why):
        assert read_link(text) == why, (vname, read_link(text))
        out("link", vname, text, "Mesh.cpp#L252", refused=why)

    # Test keys only: never a real radio's.
    companion = hashlib.sha256(b"lichen test node: companion").digest()
    repeater = hashlib.sha256(b"lichen test node: repeater").digest()
    room = hashlib.sha256(b"lichen test node: room").digest()
    sensor = hashlib.sha256(b"lichen test node: sensor").digest()
    ts = 1_793_000_000

    def url(packet, upper=False):
        h = packet.hex()
        return "meshcore://" + (h.upper() if upper else h)

    hut = advert(companion, ts, app_data(1, b"Hut radio"))
    link("link-companion", url(hut))
    link("link-companion-upper-case", url(hut, upper=True))
    link("link-repeater-position", url(advert(repeater, ts + 1, app_data(2, b"hub west", pos=(12_345_678, -98_765_432)))))
    link("link-room-feature-fields", url(advert(room, ts + 2, app_data(3, b"Refuge board", feat1=0x0102, feat2=7))))
    # The name fills app_data's 32 bytes: 31 bytes of UTF-8, then 23 with a position.
    name31 = ("é" * 15 + "s").encode()
    assert len(name31) == 31
    link("link-sensor-name-fills-app-data", url(advert(sensor, ts + 3, app_data(4, name31))))
    name23 = ("ü" * 11 + "x").encode()
    assert len(name23) == 23
    link("link-position-and-longest-name", url(advert(sensor, ts + 4, app_data(4, name23, pos=(-1, 1)))))
    # A position of 0, 0 is none, as the radio reports it (§16.1).
    link("link-position-zero-is-none", url(advert(companion, ts + 5, app_data(1, b"Hut radio", pos=(0, 0)))))
    # A contact's kept advert carries the path it came by: read, reported and imported with it.
    link("link-with-2-hop-path", url(advert(repeater, ts + 6, app_data(2, b"crest"), path=bytes([0x5A, 0x77]))))
    link("link-with-2-byte-path", url(advert(room, ts + 7, app_data(3, b"Refuge board"),
                                              path=bytes([0x5A, 0x01, 0x77, 0x02]), path_len=0x42)))

    # Refused: not a link, or a signature that does not verify.
    good = advert(companion, ts, app_data(1, b"Hut radio"))
    changed = bytearray(good)
    changed[-1] ^= 0x01
    refused("link-bad-signature", url(bytes(changed)), "signature")
    other = advert(repeater, ts, app_data(1, b"Hut radio"))
    refused("link-signed-by-another-key", url(ed25519_public(companion).join([good[:2], other[34:]])), "signature")
    refused("link-trailing-byte", url(good + b"!"), "signature")
    refused("link-timestamp-changed", url(good[:34] + struct.pack("<I", ts + 1) + good[38:]), "signature")
    refused("link-direct-route", url(bytes([0x12]) + good[1:]), "code")
    refused("link-transport-flood", url(bytes([0x10]) + good[1:]), "code")
    refused("link-not-an-advert", url(bytes([0x15]) + good[1:]), "code")
    refused("link-version-1", url(bytes([0x51]) + good[1:]), "code")
    refused("link-truncated-signature", url(good[:2 + 32 + 4 + 40]), "code")
    refused("link-no-app-data", url(good[:2 + 32 + 4 + 64]), "code")
    refused("link-odd-length", url(good)[:-1], "code")
    refused("link-not-hex", url(good)[:-2] + "zz", "code")
    refused("link-empty", "meshcore://", "code")
    refused("link-bad-path-length", url(advert(companion, ts, app_data(1, b"Hut radio"), path_len=0xC1, path=b"\0")), "code")
    refused("link-path-past-the-end", url(good[:1] + bytes([63])), "code")
    refused("link-app-data-33-bytes", url(advert(sensor, ts, app_data(4, name31 + b"s"))), "code")
    refused("link-type-0", url(advert(companion, ts, app_data(0, b"Hut radio"))), "code")
    refused("link-type-5", url(advert(companion, ts, app_data(5, b"Hut radio"))), "code")
    refused("link-no-name", url(advert(companion, ts, app_data(1, b""))), "code")
    refused("link-name-not-utf8", url(advert(companion, ts, app_data(1, b"Hut \xff"))), "code")
    refused("link-name-with-nul", url(advert(companion, ts, app_data(1, b"Hut\0radio"))), "code")
    refused("link-position-cut-short", url(advert(companion, ts, bytes([0x91, 1, 2, 3]))), "code")
    # A contact code reads as before ([[qr]]); lichen adds it with ADD_UPDATE_CONTACT, unsigned.
    key = bytes(range(0xA0, 0xC0))
    code = f"meshcore://contact/add?name=ThinkNode%20M5&public_key={key.hex()}&type=1"
    assert read_contact(code) == ("ThinkNode M5", key, 1)
    out("link", "link-contact-code", code, "MyMesh.cpp#L1328", contact_name="ThinkNode M5",
        public_key=key, node_type=1, timestamp=0, signed=False, hops=0, path=b"",
        add_frame=add_frame(key, 1, "ThinkNode M5", 0, None))

main()
